    if (leafScoreMode == null) {
      leafScoreMode = collector.scoreMode();
    } else if (leafScoreMode != collector.scoreMode()) {
      leafScoreMode = ScoreMode.COMPLETE;
    }
    leafCollectors.add(leafCollector);
