  if (leafCollectors.isEmpty()) {
    throw new CollectionTerminatedException();
  } else {
    // Wraps single leaf collector that wants to skip low-scoring hits (ScoreMode.TOP_SCORES)
    // but the global score mode doesn't allow it.
